import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const contractUrl = new URL('../openapi.yaml', import.meta.url);
const generatedUrl = new URL('../../frontend/src/app/api/generated/openapi.ts', import.meta.url);
const generatedHeader = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;
const expected = generatedHeader + astToString(await openapiTS(contractUrl));

let actual;
try {
  actual = await readFile(fileURLToPath(generatedUrl), 'utf8');
} catch {
  console.error('Thiếu DTO được sinh. Chạy npm run generate trong app/contracts.');
  process.exitCode = 1;
}

if (actual !== undefined && actual !== expected) {
  console.error('DTO frontend đã lệch OpenAPI. Chạy npm run generate trong app/contracts.');
  process.exitCode = 1;
}
